CREATE TABLE public.creator_heart_totals (creator_id uuid PRIMARY KEY, hearts bigint NOT NULL DEFAULT 0 CHECK (hearts >= 0));
GRANT SELECT ON public.creator_heart_totals TO anon, authenticated;
GRANT ALL ON public.creator_heart_totals TO service_role;
ALTER TABLE public.creator_heart_totals ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public aggregate hearts only" ON public.creator_heart_totals FOR SELECT TO anon, authenticated USING (true);
INSERT INTO public.creator_heart_totals (creator_id, hearts) SELECT creator_id, count(*) FROM public.creator_hearts GROUP BY creator_id;
CREATE FUNCTION public.sync_creator_heart_total() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO public.creator_heart_totals(creator_id,hearts) VALUES(NEW.creator_id,1) ON CONFLICT(creator_id) DO UPDATE SET hearts=creator_heart_totals.hearts+1; ELSE UPDATE public.creator_heart_totals SET hearts=greatest(0,hearts-1) WHERE creator_id=OLD.creator_id; END IF; RETURN NULL; END $$;
REVOKE ALL ON FUNCTION public.sync_creator_heart_total() FROM PUBLIC;
CREATE TRIGGER sync_creator_heart_total AFTER INSERT OR DELETE ON public.creator_hearts FOR EACH ROW EXECUTE FUNCTION public.sync_creator_heart_total();
ALTER PUBLICATION supabase_realtime ADD TABLE public.creator_heart_totals;
ALTER TABLE public.creator_media ADD COLUMN teaser_frame text NOT NULL DEFAULT 'none' CHECK(teaser_frame IN ('none','seasonal','sexy','gothic','glamour')), ADD COLUMN active_from timestamptz, ADD COLUMN active_until timestamptz;
CREATE INDEX creator_media_active_teasers ON public.creator_media(creator_id,active_until) WHERE bucket='teasers';
CREATE FUNCTION public.set_my_active_teaser(_media_id uuid, _period text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE owner_id uuid:=auth.uid(); BEGIN IF owner_id IS NULL OR _period NOT IN ('day','month') THEN RAISE EXCEPTION 'Invalid teaser selection'; END IF; PERFORM 1 FROM public.profiles WHERE user_id=owner_id FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.creator_media WHERE id=_media_id AND creator_id=owner_id AND bucket='teasers') THEN RAISE EXCEPTION 'Teaser not found'; END IF; UPDATE public.creator_media SET active_from=NULL,active_until=NULL WHERE creator_id=owner_id AND bucket='teasers'; UPDATE public.creator_media SET active_from=now(),active_until=now()+CASE WHEN _period='day' THEN interval '1 day' ELSE interval '1 month' END WHERE id=_media_id AND creator_id=owner_id; END $$;
REVOKE ALL ON FUNCTION public.set_my_active_teaser(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_my_active_teaser(uuid,text) TO authenticated;
CREATE FUNCTION public.get_active_teasers() RETURNS SETOF public.creator_media LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT DISTINCT ON (creator_id) m.* FROM public.creator_media m WHERE bucket='teasers' ORDER BY creator_id, (active_from<=now() AND active_until>now()) DESC NULLS LAST, created_at DESC $$;
REVOKE ALL ON FUNCTION public.get_active_teasers() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_active_teasers() TO authenticated;
ALTER TABLE public.custom_requests ADD COLUMN origin_country text;
UPDATE public.custom_requests r SET origin_country=p.country FROM public.profiles p WHERE p.user_id=r.customer_id AND p.country IS NOT NULL;
CREATE FUNCTION public.snapshot_request_country() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN SELECT nullif(country,'') INTO NEW.origin_country FROM public.profiles WHERE user_id=NEW.customer_id; ELSE NEW.origin_country:=OLD.origin_country; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.snapshot_request_country() FROM PUBLIC;
CREATE TRIGGER snapshot_request_country BEFORE INSERT OR UPDATE ON public.custom_requests FOR EACH ROW EXECUTE FUNCTION public.snapshot_request_country();
CREATE INDEX custom_requests_creator_country ON public.custom_requests(creator_id,origin_country,created_at DESC);